    adcs_status_t status = ADCS_OK;
    int valid_enable = (mb_input.enable == 1);
    int invalid_enable = (mb_input.enable != 0 && mb_input.enable != 1);

    // 1. Input Validation
    if (invalid_enable || 
        mb_input.wheel_count != 4 || 
        mb_input.wheels == NULL ||
        !adcs_is_finite_vec3(&mb_config.target_nms) ||
        !isfinite(mb_config.kp_s_inv) || !isfinite(mb_config.ki_s2_inv) ||
        !isfinite(mb_config.dt_s) || !isfinite(mb_config.torque_limit_nm) ||
        !isfinite(mb_config.max_wheel_speed_rad_s) ||
        !isfinite(mb_config.integral_limit_nms_s) ||
        !isfinite(mb_config.enter_error_nms) || !isfinite(mb_config.exit_error_nms) ||
        !isfinite(mb_config.target_slew_nms_per_cycle) ||
        !isfinite((double)mb_config.settle_cycles)) {
        mb_state.mode = MB_FAULT;
        goto fault_output;
    }

    for (size_t i = 0; i < 4; ++i) {
        if (!isfinite(mb_input.wheels[i].speed_rad_s) || fabs(mb_input.wheels[i].speed_rad_s) > mb_config.max_wheel_speed_rad_s) {
            mb_state.mode = MB_FAULT;
            goto fault_output;
        }
    }

    if (mb_config.enter_error_nms >= mb_config.exit_error_nms ||
        mb_config.target_slew_nms_per_cycle <= 0.0 ||
        mb_config.dt_s <= 0.0 ||
        mb_config.kp_s_inv < 0.0 ||
        mb_config.ki_s2_inv < 0.0 ||
        mb_config.torque_limit_nm <= 0.0 ||
        mb_config.integral_limit_nms_s <= 0.0 ||
        mb_config.settle_cycles < 1 || mb_config.settle_cycles > 20) {
        mb_state.mode = MB_FAULT;
        goto fault_output;
    }

    // 2. State Initialization / Recovery
    int first_call = !mb_state.target_initialized;
    int just_unfaulted = (mb_state.mode == MB_FAULT && valid_enable);
    int just_enabled = (first_call && valid_enable);

    if (just_unfaulted || just_enabled || mb_state.mode == MB_OFF) {
        adcs_vec3_t mom;
        status = adcs_wheel_momentum(mb_input.wheels, 4, &mom);
        if (status != ADCS_OK) {
             mb_state.mode = MB_FAULT;
             goto fault_output;
        }
        mb_state.commanded_target_nms = mom;
        mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
        mb_state.settled = 0;
        mb_state.target_initialized = 1;
        mb_state.mode = MB_RAMP;
    } else if (valid_enable) {
        // Check if target changed significantly
        double dx = mb_config.target_nms.x - mb_state.commanded_target_nms.x;
        double dy = mb_config.target_nms.y - mb_state.commanded_target_nms.y;
        double dz = mb_config.target_nms.z - mb_state.commanded_target_nms.z;
        double diff_sq = dx*dx + dy*dy + dz*dz;

        if (diff_sq > 1e-20) {
             mb_state.mode = MB_RAMP;
             mb_state.settled = 0;
        }
    }

    // 3. Compute Momentum and Error
    adcs_vec3_t momentum_nms;
    status = adcs_wheel_momentum(mb_input.wheels, 4, &momentum_nms);
    if (status != ADCS_OK) {
        mb_state.mode = MB_FAULT;
        goto fault_output;
    }

    adcs_vec3_t error_nms = adcs_vec3_sub(&momentum_nms, &mb_state.commanded_target_nms);
    double error_norm = adcs_vec3_norm(&error_nms);

    // 4. Mode Execution
    adcs_vec3_t torque_nm = {0,0,0};
    unint32 sat_mask = 0;

    if (mb_state.mode == MB_RAMP) {
        // Update Target towards target_nms
        adcs_vec3_t delta_target = adcs_vec3_sub(&mb_config.target_nms, &mb_state.commanded_target_nms);
        double delta_norm = adcs_vec3_norm(&delta_target);
        if (delta_norm > mb_config.target_slew_nms_per_cycle) {
            delta_target = adcs_vec3_scale(&delta_target, mb_config.target_slew_nms_per_cycle / delta_norm);
        }
        mb_state.commanded_target_nms = adcs_vec3_add(&mb_state.commanded_target_nms, &delta_target);

        // Recompute error after target move
        error_nms = adcs_vec3_sub(&momentum_nms, &mb_state.commanded_target_nms);
        error_norm = adcs_vec3_norm(&error_nms);

        // Proportional Control Only
        torque_nm = adcs_vec3_scale(&error_nms, -mb_config.kp_s_inv);

        // Clear Integral
        mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};

        // Check Transition to BIAS
        if (error_norm <= mb_config.enter_error_nms) {
            mb_state.mode = MB_BIAS;
            mb_state.settled = 0;
        }

    } else if (mb_state.mode == MB_BIAS || mb_state.mode == MB_HOLD) {
        // PI Control
        adcs_vec3_t integral_prev = mb_state.integral_error_nms_s;
        adcs_vec3_t integral_cand = adcs_vec3_add(&integral_prev, &adcs_vec3_scale(&error_nms, mb_config.dt_s));

        // Clamp Integral
        integral_cand.x = ADCS_CLAMP(integral_cand.x, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);
        integral_cand.y = ADCS_CLAMP(integral_cand.y, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);
        integral_cand.z = ADCS_CLAMP(integral_cand.z, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);

        // Proposed Torque
        adcs_vec3_t torque_p = adcs_vec3_add(
            &adcs_vec3_scale(&error_nms, -mb_config.kp_s_inv),
            &adcs_vec3_scale(&integral_cand, -mb_config.ki_s2_inv)
        );

        // Saturation Handling & Axis-wise Limiting
        for (int i = 0; i < 3; ++i) {
            double t_val = torque_p.x;
            if (i==1) t_val = torque_p.y;
            if (i==2) t_val = torque_p.z;

            if (fabs(t_val) <= mb_config.torque_limit_nm) {
                if (i==0) torque_nm.x = t_val;
                if (i==1) torque_nm.y = t_val;
                if (i==2) torque_nm.z = t_val;
            } else {
                sat_mask |= (1U << i);
                double old_t_val = 0;
                if (i==0) old_t_val = -mb_config.kp_s_inv * error_nms.x - mb_config.ki_s2_inv * integral_prev.x;
                if (i==1) old_t_val = -mb_config.kp_s_inv * error_nms.y - mb_config.ki_s2_inv * integral_prev.y;
                if (i==2) old_t_val = -mb_config.kp_s_inv * error_nms.z - mb_config.ki_s2_inv * integral_prev.z;

                if (fabs(old_t_val) <= mb_config.torque_limit_nm) {
                     if (i==0) torque_nm.x = old_t_val;
                     if (i==1) torque_nm.y = old_t_val;
                     if (i==2) torque_nm.z = old_t_val;
                } else {
                     if (i==0) torque_nm.x = copysign(mb_config.torque_limit_nm, t_val);
                     if (i==1) torque_nm.y = copysign(mb_config.torque_limit_nm, t_val);
                     if (i==2) torque_nm.z = copysign(mb_config.torque_limit_nm, t_val);
                }
            }
        }

        // Update Integral State (Freeze if saturated)
        for (int i = 0; i < 3; ++i) {
             double p_val = torque_p.x;
             if (i==1) p_val = torque_p.y;
             if (i==2) p_val = torque_p.z;

             if (fabs(p_val) > mb_config.torque_limit_nm) {
                 // Frozen: keep old integral
                 if (i==0) mb_state.integral_error_nms_s.x = integral_prev.x;
                 if (i==1) mb_state.integral_error_nms_s.y = integral_prev.y;
                 if (i==2) mb_state.integral_error_nms_s.z = integral_prev.z;
             } else {
                 if (i==0) mb_state.integral_error_nms_s.x = integral_cand.x;
                 if (i==1) mb_state.integral_error_nms_s.y = integral_cand.y;
                 if (i==2) mb_state.integral_error_nms_s.z = integral_cand.z;
             }
        }

        // Mode Transitions
        if (mb_state.mode == MB_BIAS) {
            if (error_norm <= mb_config.enter_error_nms) {
                mb_state.settled++;
                if (mb_state.settled >= mb_config.settle_cycles) {
                    mb_state.mode = MB_HOLD;
                }
            } else {
                mb_state.settled = 0;
            }
        } else if (mb_state.mode == MB_HOLD) {
            if (error_norm >= mb_config.exit_error_nms) {
                mb_state.mode = MB_BIAS;
                mb_state.settled = 0;
            }
        }
    }

    // 5. Output Assignment
    mb_output.mode = mb_state.mode;
    mb_output.momentum_nms = momentum_nms;
    mb_output.commanded_target_nms = mb_state.commanded_target_nms;
    mb_output.error_nms = error_nms;
    mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
    mb_output.torque_nm = torque_nm;
    mb_output.saturation_mask = sat_mask;
    mb_output.settled = mb_state.settled;
    return;

fault_output:
    mb_output.mode = MB_FAULT;
    mb_output.momentum_nms = (adcs_vec3_t){0,0,0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0,0,0};
    mb_output.error_nms = (adcs_vec3_t){0,0,0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0,0,0};
    mb_output.torque_nm = (adcs_vec3_t){0,0,0};
    mb_output.saturation_mask = 0;
    mb_output.settled = 0;

